import { useEffect, useRef, useState } from "react";

// Artwork embedded so this component works without uploading or resolving asset paths.
const punchSrc = "data:image/png;base64,";

/**
 * PUNCH as inflated material.
 *
 * The artwork's silhouette is turned into a real volume at load and lit live, so a
 * press can deform the surface itself: the dent lands at once, with an irregular
 * outline, a rim of material pushed up around it, radial creases and one ripple,
 * and then it comes back slowly, the way memory foam does.
 *
 * Press is the only action available. It listens for pointerdown, not click:
 * a punch happens when the hand arrives, not when it leaves.
 */

/* ---------------- material ---------------- */

type Material = "leather" | "clay";

type Preset = {
  // timing (ms)
  pressMs: number;
  holdMs: number;
  recoverMs: number;
  residual: number; // fraction of the dent that never comes back
  overshoot: number; // sinks a little further, then settles
  wobble: number; // small jelly oscillation while recovering
  // dent shape (image heights)
  radius: number;
  amp: number;
  rim: number; // material pushed up around the dent
  wrinkle: number; // radial creases
  ripple: number;
  // surface
  spec: number;
  shine: number;
  broad: number;
  micro: number; // fine pores
  print: number; // fingerprint ridges
  sat: number;
  pitch: number; // of the thump
};

const PRESETS: Record<Material, Preset> = {
  // glossy inflated vinyl: the dent comes back
  leather: {
    pressMs: 60, holdMs: 160, recoverMs: 1500, residual: 0, overshoot: 0.1, wobble: 0.05,
    radius: 0.34, amp: 0.1, rim: 0.4, wrinkle: 1.0, ripple: 0.09,
    spec: 0.38, shine: 30, broad: 0.14, micro: 0.007, print: 0, sat: 1.24, pitch: 1,
  },
  // matte plasticine: the dent mostly stays
  clay: {
    pressMs: 90, holdMs: 0, recoverMs: 2800, residual: 0.82, overshoot: 0, wobble: 0,
    radius: 0.3, amp: 0.085, rim: 0.6, wrinkle: 0.25, ripple: 0,
    spec: 0.07, shine: 9, broad: 0.05, micro: 0.03, print: 1, sat: 1.05, pitch: 0.7,
  },
};

const SLOTS = 10; // shader slots, including dents that are fading out
const MAX_ALIVE = 8;
const FADE_MS = 350;
const EDGE = 0.02; // transparent margin inside the canvas, per side

// shape of the inflated volume
const MAP_W = 1024;
const MAP_MARGIN = 0.05; // of map width
const INFLATE = 0.105; // inflation radius, in map heights
const THICK = 0.26; // cushion thickness, in image heights
const GROW = 0.004; // how far letters swell into the gaps between them
const SEAM = 3.0; // how deep the artwork's own shadow lines cut between letters
const FLOOR = 0.5; // a crease never sinks below this share of the full thickness
const EDGE_KEEP = 0.004; // seams fade out this close to the silhouette, in map heights
const KEY_TOL = 46; // how far from the background colour a pixel must be to count as a letter,
// used only when the image arrives with no transparency of its own
const GMAX = 9; // largest slope the shape map can hold. A circular profile stands up
// almost vertically at the rim, so a low ceiling clips the normals flat there and the
// highlight turns a hard corner across the clipped band.

type Dent = {
  x: number; // image uv
  y: number;
  r: number;
  seed: number;
  t0: number;
  released: number | null;
  dying: number | null;
  pointerId: number;
};

function depthOf(d: Dent, now: number, P: Preset) {
  const t = now - d.t0;
  const s = Math.min(t / P.pressMs, 1);
  let depth = 1 - Math.pow(1 - s, 3); // lands at once
  const u = Math.min(Math.max((t - P.pressMs) / 140, 0), 1);
  depth += P.overshoot * Math.sin(Math.PI * u); // soft body: sinks further, settles
  if (d.released !== null) {
    const since = now - Math.max(d.released, d.t0 + P.pressMs) - P.holdMs;
    if (since > 0) {
      const k = Math.exp(-Math.pow(since / P.recoverMs, 1.4)); // slow start, long tail
      depth *= P.residual + (1 - P.residual) * k;
      depth *= 1 + P.wobble * Math.sin(since * 0.011) * Math.exp(-since / 280);
    }
  }
  if (d.dying !== null) depth *= Math.max(0, 1 - (now - d.dying) / FADE_MS);
  return depth;
}

/* ---------------- shape maps, built once on the CPU ---------------- */

// Exact Euclidean distance transform (Felzenszwalb & Huttenlocher). A chamfer
// approximation leaves concentric rings along the outline, which the specular
// highlight then amplifies into visible bands, so the exact one is worth it.
function edt1d(f: Float32Array, n: number, out: Float32Array, v: Int32Array, zs: Float32Array) {
  let k = 0;
  v[0] = 0;
  zs[0] = -Infinity;
  zs[1] = Infinity;
  for (let q = 1; q < n; q++) {
    let s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    while (s <= zs[k]) {
      k--;
      s = (f[q] + q * q - (f[v[k]] + v[k] * v[k])) / (2 * q - 2 * v[k]);
    }
    k++;
    v[k] = q;
    zs[k] = s;
    zs[k + 1] = Infinity;
  }
  k = 0;
  for (let q = 0; q < n; q++) {
    while (zs[k + 1] < q) k++;
    const dq = q - v[k];
    out[q] = dq * dq + f[v[k]];
  }
}

function distanceTo(zero: Uint8Array, w: number, h: number) {
  const INF = 1e12;
  const d = new Float32Array(w * h);
  for (let i = 0; i < d.length; i++) d[i] = zero[i] ? 0 : INF;

  const m = Math.max(w, h);
  const f = new Float32Array(m);
  const out = new Float32Array(m);
  const v = new Int32Array(m);
  const zs = new Float32Array(m + 1);

  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) f[y] = d[y * w + x];
    edt1d(f, h, out, v, zs);
    for (let y = 0; y < h; y++) d[y * w + x] = out[y];
  }
  for (let y = 0; y < h; y++) {
    const row = y * w;
    for (let x = 0; x < w; x++) f[x] = d[row + x];
    edt1d(f, w, out, v, zs);
    for (let x = 0; x < w; x++) d[row + x] = Math.sqrt(out[x]);
  }
  return d;
}

function boxBlur(a: Float32Array, w: number, h: number, r: number, passes: number): Float32Array {
  let src: Float32Array = a;
  let dst: Float32Array = new Float32Array(a.length);
  const tmp = new Float32Array(a.length);
  for (let p = 0; p < passes; p++) {
    for (let y = 0; y < h; y++)
      for (let x = 0; x < w; x++) {
        let s = 0;
        for (let k = -r; k <= r; k++) s += src[y * w + Math.min(w - 1, Math.max(0, x + k))];
        tmp[y * w + x] = s / (2 * r + 1);
      }
    for (let y = 0; y < h; y++)
      for (let x = 0; x < w; x++) {
        let s = 0;
        for (let k = -r; k <= r; k++) s += tmp[Math.min(h - 1, Math.max(0, y + k)) * w + x];
        dst[y * w + x] = s / (2 * r + 1);
      }
    [src, dst] = [dst, src];
  }
  return src;
}

function buildMaps(img: HTMLImageElement, squeeze: number) {
  const imgAspect = (img.naturalWidth / img.naturalHeight) * squeeze;
  const mpx = Math.round(MAP_W * MAP_MARGIN);
  const artW = MAP_W - 2 * mpx;
  const artH = Math.round(artW / imgAspect);
  const W = MAP_W;
  const H = artH + 2 * mpx;
  const N = W * H;

  const cv = document.createElement("canvas");
  cv.width = W;
  cv.height = H;
  const cx = cv.getContext("2d", { willReadFrequently: true })!;
  cx.drawImage(img, mpx, mpx, artW, artH); // squeezed horizontally: the letters sit closer
  const px = cx.getImageData(0, 0, W, H).data;

  // Which pixels are letters. Normally that is the PNG's own transparency, but an
  // upload can arrive flattened onto a solid background — and then every pixel is
  // opaque, the whole frame counts as material, and the word inflates into one
  // rectangle. So when there is no transparency to read, key the background out by
  // colour instead, sampling it from the corners.
  const x0 = mpx, y0 = mpx, x1 = mpx + artW, y1 = mpx + artH;
  const drawn = artW * artH;
  let clear = 0;
  for (let i = 0; i < N; i++) if (px[i * 4 + 3] <= 127) clear++;
  const keyed = clear - (N - drawn) < drawn * 0.02;

  let bgR = 0, bgG = 0, bgB = 0;
  if (keyed) {
    const pts = [[x0 + 2, y0 + 2], [x1 - 3, y0 + 2], [x0 + 2, y1 - 3], [x1 - 3, y1 - 3]];
    for (const [cxp, cyp] of pts) {
      const i = (cyp * W + cxp) * 4;
      bgR += px[i] / 4;
      bgG += px[i + 1] / 4;
      bgB += px[i + 2] / 4;
    }
  }

  // The artwork carries grain, so thresholding raw colour distance would make the mask
  // speckle along every edge and the surface would come out lumpy. Smooth the distance
  // first, then cut.
  let keyDist: Float32Array | null = null;
  if (keyed) {
    const raw = new Float32Array(N);
    for (let y = y0; y < y1; y++)
      for (let x = x0; x < x1; x++) {
        // the margin stays at zero: it is empty canvas, not background, and its huge
        // distance from the keyed colour would otherwise blur inward as a false edge
        const i = y * W + x;
        const dr = px[i * 4] - bgR;
        const dg = px[i * 4 + 1] - bgG;
        const db = px[i * 4 + 2] - bgB;
        raw[i] = Math.sqrt(dr * dr + dg * dg + db * db);
      }
    keyDist = boxBlur(raw, W, H, 2, 2);
  }

  const inside = new Uint8Array(N);
  const outside = new Uint8Array(N);
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      let on: boolean;
      if (x < x0 || y < y0 || x >= x1 || y >= y1) {
        on = false; // the margin we left around the artwork
      } else if (keyDist) {
        on = keyDist[i] > KEY_TOL;
      } else {
        on = px[i * 4 + 3] > 127;
      }
      inside[i] = on ? 1 : 0;
      outside[i] = on ? 0 : 1;
    }
  const dIn0 = distanceTo(outside, W, H); // depth inside the original letters
  const dOut = distanceTo(inside, W, H); // distance from the letters, in the gaps

  // Keep the packed composition, but give each cushion its own rounded volume.
  const owner = new Uint8Array(N);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const sx = (x - mpx) / artW * 1108;
    const sy = (y - mpx) / artH * 481;
    const pn = 377 + 4 * Math.sin(sy / 90);
    const nc = 566 + 3 * Math.sin(sy / 110);
    const ch = 858 + 5 * Math.sin(sy / 85);
    owner[y * W + x] = sx >= ch ? 4 : sx >= nc ? 3 : sx >= pn ? 2 :
      (sy > 220 && sx > 195 - 25 * Math.max(0, 1 - (sy - 220) / 82) ? 1 : 0);
  }
  // Only the cushion underneath receives contact shade; surfaces stay independent.
  const layerRank = [3, 4, 2, 3, 1]; // P, U, N, C, H
  const contactMask = new Float32Array(N);
  for (let letter = 0; letter < 5; letter++) {
    const front = new Uint8Array(N);
    for (let i = 0; i < N; i++) {
      front[i] = inside[i] && layerRank[owner[i]] > layerRank[letter] ? 1 : 0;
    }
    const frontDistance = distanceTo(front, W, H);
    for (let i = 0; i < N; i++) if (owner[i] === letter) {
      contactMask[i] = Math.exp(-Math.pow(frontDistance[i] / 6, 2));
    }
  }
  const R = INFLATE * H;
  const G = GROW * H;

  // The counters — the hole in the P, the pockets between letters — are enclosed, so a
  // flood fill from the border never reaches them. Keeping them out of the growth is
  // what stops the word closing up into one blob once it is inflated.
  const bg = new Uint8Array(N);
  const stack: number[] = [];
  for (let x = 0; x < W; x++) stack.push(x, (H - 1) * W + x);
  for (let y = 0; y < H; y++) stack.push(y * W, y * W + W - 1);
  while (stack.length) {
    const i = stack.pop()!;
    if (bg[i] || inside[i]) continue;
    bg[i] = 1;
    const x = i % W;
    const y = (i - x) / W;
    if (x > 0) stack.push(i - 1);
    if (x < W - 1) stack.push(i + 1);
    if (y > 0) stack.push(i - W);
    if (y < H - 1) stack.push(i + W);
  }

  // letters swell into the outside gaps only, until neighbours touch
  const grown = new Uint8Array(N);
  for (let i = 0; i < N; i++) grown[i] = inside[i] || (bg[i] && dOut[i] <= G) ? 1 : 0;
  const notGrown = new Uint8Array(N);
  for (let i = 0; i < N; i++) notGrown[i] = grown[i] ? 0 : 1;
  const dD = distanceTo(notGrown, W, H);
  const letterDepth = new Float32Array(N);
  for (let letter = 0; letter < 5; letter++) {
    const exterior = new Uint8Array(N);
    for (let i = 0; i < N; i++) exterior[i] = !grown[i] || owner[i] !== letter ? 1 : 0;
    const distance = distanceTo(exterior, W, H);
    for (let i = 0; i < N; i++) if (owner[i] === letter) letterDepth[i] = distance[i];
  }


  // Where one letter ends and the next begins is already drawn into the artwork, as the
  // soft dark lines between overlapping letters (checked: the whole word is a single
  // connected shape, so there is no gap to find it from geometrically). A high pass over
  // the artwork's own brightness isolates those lines and drops the broad colour
  // gradient, so the seams follow the drawing rather than a guess.
  const lum = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    lum[i] = inside[i] ? (0.299 * px[i * 4] + 0.587 * px[i * 4 + 1] + 0.114 * px[i * 4 + 2]) / 255 : 0;
  }
  // low pass on a quarter-size grid, so the blur is wide enough to keep only the shading
  const LC = 4;
  const LW = Math.ceil(W / LC);
  const LH = Math.ceil(H / LC);
  const lSum = new Float32Array(LW * LH);
  const lCnt = new Float32Array(LW * LH);
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      if (!inside[i]) continue;
      const c = Math.floor(y / LC) * LW + Math.floor(x / LC);
      lSum[c] += lum[i];
      lCnt[c] += 1;
    }
  const lSumB: Float32Array = boxBlur(lSum, LW, LH, 16, 2);
  const lCntB: Float32Array = boxBlur(lCnt, LW, LH, 16, 2);
  const lowAt = (x: number, y: number) => {
    const c = Math.min(LH - 1, Math.floor(y / LC)) * LW + Math.min(LW - 1, Math.floor(x / LC));
    return lCntB[c] > 1e-4 ? lSumB[c] / lCntB[c] : 0.5;
  };

  // The high pass is sharp, and cutting it straight into the height gives hard, creased
  // folds — the piece stops reading as something with air in it. Softening the crease
  // field first, and letting it sink only part way, keeps the seams legible while the
  // surface stays inflated.
  const creaseRaw = new Float32Array(N);
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      if (!inside[i]) continue;
      const hp = lum[i] - lowAt(x, y); // negative in the drawn shadow lines
      // The artwork is also dark along its own outer edge. Fading the seam out near the
      // silhouette keeps that from being read as a crease, which would draw a dark
      // outline around the whole word; it also drops the noisiest part of the high pass.
      const edgeFade = Math.min(1, Math.max(0, (dIn0[i] - EDGE_KEEP * H) / (EDGE_KEEP * H)));
      creaseRaw[i] = Math.max(0, -hp) * SEAM * edgeFade; // only the darker side cuts in
    }
  const creaseSoft = boxBlur(creaseRaw, W, H, 6, 2);

  // circular cross-section: a tube of material under pressure, not a flattened dome
  const dome = (t: number) => Math.sqrt(Math.max(0, 1 - (1 - t) * (1 - t)));
  const z = new Float32Array(N);
  const seamRaw = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    if (!grown[i]) continue;
    const body = dome(Math.min((letterDepth[i] + 2) / R, 1));
    const crease = creaseSoft[i] * 0.18;
    seamRaw[i] = Math.min(1, crease / Math.max(body, 0.001));
    // the crease dips, it never cuts through: the letters stay one piece of material
    z[i] = Math.max(body - crease, body * FLOOR) * THICK;
  }
  // Smooth each letter independently: mixing heights across the occlusion edge
  // creates a membrane connecting the two cushions.
  const zb = new Float32Array(N);
  for (let letter = 0; letter < 5; letter++) {
    const values = new Float32Array(N), weights = new Float32Array(N);
    for (let i = 0; i < N; i++) if (owner[i] === letter) { values[i] = z[i]; weights[i] = 1; }
    const smoothZ = boxBlur(values, W, H, 4, 2);
    const smoothW = boxBlur(weights, W, H, 4, 2);
    for (let i = 0; i < N; i++) if (owner[i] === letter) zb[i] = smoothZ[i] / Math.max(smoothW[i], 0.001);
  }

  // Occlusion lives in its own map rather than being read off the height. Read off the
  // height it would also darken the outer silhouette, and the word would look like a
  // sticker with a drawn outline.
  const seamSoft = boxBlur(seamRaw, W, H, 4, 2);
  const contactSoft = boxBlur(contactMask, W, H, 2, 2);
  const occlusion = new Uint8Array(N * 4);
  for (let i = 0; i < N; i++) {
    occlusion[i * 4] = Math.round(Math.min(1, Math.max(seamRaw[i], seamSoft[i] * 1.1)) * 255);
    occlusion[i * 4 + 1] = Math.round(contactSoft[i] * 255);
    occlusion[i * 4 + 3] = 255;
  }

  const shape = new Uint8Array(N * 4);
  const enc = (g: number) => Math.round(Math.min(1, Math.max(0, (g / GMAX) * 0.5 + 0.5)) * 255);
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      const left = y * W + Math.max(0, x - 1), right = y * W + Math.min(W - 1, x + 1);
      const up = Math.max(0, y - 1) * W + x, down = Math.min(H - 1, y + 1) * W + x;
      const slope = (a: number, b: number) => {
        if (owner[a] !== owner[i]) return zb[b] - zb[i];
        if (owner[b] !== owner[i]) return zb[i] - zb[a];
        return (zb[b] - zb[a]) / 2;
      };
      shape[i * 4] = enc(slope(left, right) * H);
      shape[i * 4 + 1] = enc(slope(up, down) * H);
      shape[i * 4 + 2] = Math.round(Math.min(1, zb[i] / THICK) * 255);
      const a = inside[i] ? 1 : Math.min(1, Math.max(0, G - dOut[i] + 0.5));
      shape[i * 4 + 3] = Math.round(a * 255);
    }

  // Albedo: the artwork's own colours, pushed outward so every inflated pixel has one.
  // Samples are weighted by how deep inside a stroke they sit, which drops the artwork's
  // baked-in edge shading and its grain — those would fight the live lighting — while
  // keeping the colour gradient.
  const CELL = 4;
  const AW = Math.ceil(W / CELL);
  const AH = Math.ceil(H / CELL);
  const sums = [0, 1, 2, 3].map(() => new Float32Array(AW * AH));
  const core = 0.035 * H;
  let mr = 0, mg = 0, mb = 0, mw = 0;
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) {
      const i = y * W + x;
      if (!inside[i]) continue;
      const wgt = Math.pow(Math.min(1, letterDepth[i] / core), 2);
      if (wgt <= 0) continue;
      const c = Math.floor(y / CELL) * AW + Math.floor(x / CELL);
      sums[0][c] += px[i * 4] * wgt;
      sums[1][c] += px[i * 4 + 1] * wgt;
      sums[2][c] += px[i * 4 + 2] * wgt;
      sums[3][c] += wgt;
      mr += px[i * 4] * wgt; mg += px[i * 4 + 1] * wgt; mb += px[i * 4 + 2] * wgt; mw += wgt;
    }
  const fallback = mw ? [mr / mw, mg / mw, mb / mw] : [240, 170, 210];
  // blur colour and weight together, repeatedly, so colour flows into the grown gaps
  let cr: Float32Array = sums[0], cg: Float32Array = sums[1], cb: Float32Array = sums[2], cw: Float32Array = sums[3];
  for (let pass = 0; pass < 3; pass++) {
    cr = boxBlur(cr, AW, AH, 6, 2);
    cg = boxBlur(cg, AW, AH, 6, 2);
    cb = boxBlur(cb, AW, AH, 6, 2);
    cw = boxBlur(cw, AW, AH, 6, 2);
  }
  const albedo = new Uint8Array(AW * AH * 4);
  for (let c = 0; c < AW * AH; c++) {
    const wgt = cw[c];
    const src = [cr, cg, cb];
    for (let k = 0; k < 3; k++) albedo[c * 4 + k] = Math.round(wgt > 1e-4 ? Math.min(255, src[k][c] / wgt) : fallback[k]);
    albedo[c * 4 + 3] = 255;
  }

  const alphaMap = new Uint8Array(N);
  for (let i = 0; i < N; i++) alphaMap[i] = shape[i * 4 + 3];

  return { W, H, aspect: W / H, shape, occlusion, albedo, AW, AH, alphaMap };
}

/* ---------------- shaders ---------------- */

const VERT = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = vec2(aPos.x * 0.5 + 0.5, 0.5 - aPos.y * 0.5);
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG = `
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 vUv;
uniform sampler2D uShape;     // rg = base slope, b = base height, a = silhouette
uniform sampler2D uAlbedo;
uniform sampler2D uOcclusion; // r = how tightly two letters meet here
uniform vec4 uDents[${SLOTS}];  // x, y (image uv), depth, radius
uniform vec4 uDentsB[${SLOTS}]; // age (s), seed, fold count, -
uniform float uAspect, uEdge, uGmax;
uniform float uAmp, uRim, uWrinkle, uRipple;
uniform float uSpec, uShine, uBroad, uMicro, uPrint, uSat;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

// height change caused by every dent, at image position p (image-height units)
float dents(vec2 p) {
  float h = 0.0;
  for (int i = 0; i < ${SLOTS}; i++) {
    vec4 d = uDents[i];
    if (d.z < 0.001) continue;
    vec4 b = uDentsB[i];
    vec2 c = vec2(d.x * uAspect, d.y);
    vec2 v = p - c;
    float len = length(v);
    float ang = atan(v.y, v.x + 0.00001);
    // an irregular outline: a real press is never a circle
    float rr = d.w * (1.0 + 0.16 * sin(ang * 2.0 + b.y * 6.283) + 0.09 * sin(ang * 3.0 + b.y * 17.0));
    float q = len / rr;
    if (q > 1.9) continue;
    float pit = q < 1.0 ? (1.0 - q * q) * (1.0 - q * q) : 0.0;
    float rq = (q - 1.05) / 0.32;
    float ring = exp(-rq * rq); // material pushed up around the pit
    float fold = sin(ang * b.z + b.y * 40.0 + q * 2.5);
    float foldMask = smoothstep(0.15, 0.55, q) * (1.0 - smoothstep(0.85, 1.35, q));
    h += d.z * uAmp * (-pit + ring * uRim + fold * foldMask * uWrinkle * 0.35);
    float rd = len - 0.9 * b.x; // one ripple, travelling outward
    h += uRipple * uAmp * exp(-b.x * 4.5) * sin(rd * 34.0) * exp(-(rd * rd) / 0.012);
  }
  return h;
}

// fingerprint ridges pressed into clay
vec2 printGrad(vec2 p) {
  vec2 g = vec2(0.0);
  for (int i = 0; i < ${SLOTS}; i++) {
    vec4 d = uDents[i];
    if (d.z < 0.001) continue;
    vec4 b = uDentsB[i];
    vec2 c = vec2(d.x * uAspect, d.y);
    vec2 v = p - c;
    float len = length(v);
    float q = len / d.w;
    if (q > 1.05) continue;
    vec2 dir = v / max(len, 0.0001);
    float ph = len * 300.0 + vnoise(p * 30.0 + b.y * 10.0) * 3.0 + sin(atan(v.y, v.x + 0.00001) * 2.0 + b.y * 6.283) * 2.0;
    g += dir * cos(ph) * (1.0 - q) * d.z;
  }
  return g;
}

void main() {
  vec2 iuv = (vUv - uEdge) / (1.0 - 2.0 * uEdge);
  if (iuv.x < 0.0 || iuv.x > 1.0 || iuv.y < 0.0 || iuv.y > 1.0) { gl_FragColor = vec4(0.0); return; }
  vec4 sh = texture2D(uShape, iuv);
  float alpha = sh.a;
  if (alpha < 0.003) { gl_FragColor = vec4(0.0); return; }

  vec2 p = vec2(iuv.x * uAspect, iuv.y);
  vec2 g = (sh.rg - 0.5) * 2.0 * uGmax;
  float baseH = sh.b;

  float e = 0.0025;
  float hc = dents(p);
  vec2 gd = vec2(dents(p + vec2(e, 0.0)) - dents(p - vec2(e, 0.0)),
                 dents(p + vec2(0.0, e)) - dents(p - vec2(0.0, e))) / (2.0 * e);
  vec2 gt = g + gd;

  // fine pores and orange peel
  vec2 mp = p * 260.0;
  float n0 = vnoise(mp);
  gt += vec2(vnoise(mp + vec2(0.7, 0.0)) - n0, vnoise(mp + vec2(0.0, 0.7)) - n0) * uMicro;
  vec2 lp = p * 40.0;
  float l0 = vnoise(lp);
  gt += vec2(vnoise(lp + vec2(0.5, 0.0)) - l0, vnoise(lp + vec2(0.0, 0.5)) - l0) * uMicro * 0.35;

  // fingerprints (clay): faint everywhere, deep inside fresh dents
  if (uPrint > 0.0) {
    float ph = (p.x * 0.8 + p.y * 0.5) * 420.0 + vnoise(p * 6.0) * 18.0 + vnoise(p * 40.0) * 2.0;
    gt += vec2(0.8, 0.5) * cos(ph) * uPrint * 0.05 * (0.4 + 0.6 * vnoise(p * 9.0));
    gt += printGrad(p) * uPrint * 0.22;
  }

  vec3 N = normalize(vec3(-gt, 1.0));
  vec3 V = vec3(0.0, 0.0, 1.0);
  vec3 L1 = normalize(vec3(-0.5, -0.65, 0.6));
  vec3 L2 = normalize(vec3(0.6, 0.45, 0.5));

  float diff = clamp(dot(N, L1) * 0.5 + 0.5, 0.0, 1.0);
  float fill = clamp(dot(N, L2) * 0.5 + 0.5, 0.0, 1.0);
  vec3 H1 = normalize(L1 + V);
  float nh = max(dot(N, H1), 0.0);
  float spec = pow(nh, uShine) * uSpec + pow(nh, max(uShine * 0.15, 2.0)) * uBroad;
  vec3 H2 = normalize(L2 + V);
  float rim = pow(max(dot(N, H2), 0.0), 18.0) * 0.35 * uSpec;
  float fres = pow(1.0 - max(N.z, 0.0), 3.0);

  vec3 alb = texture2D(uAlbedo, iuv).rgb;
  float lum = dot(alb, vec3(0.299, 0.587, 0.114));
  alb = clamp(mix(vec3(lum), alb, uSat), 0.0, 1.0);

  float cav = clamp(-hc / (uAmp * 0.8), 0.0, 1.0);
  vec3 col = alb * (0.62 + 0.3 * diff * diff + 0.24 * fill * vec3(0.94, 0.97, 1.04));
  col *= 1.0 - 0.1 * cav * cav; // the pit softens, it does not blacken
  // a seam is a soft shadow between two packed cushions, never a drawn line
  vec2 occlusion = texture2D(uOcclusion, iuv).rg;
  float occ = occlusion.r;
  float closedSeam = occlusion.g;
  col *= mix(1.0, 0.78, smoothstep(0.2, 0.92, occ));
  col += (spec + rim) * vec3(1.0, 0.98, 0.95) * (1.0 - 0.3 * cav) * (1.0 - 0.7 * smoothstep(0.35, 0.95, occ)) * (1.0 - closedSeam * 0.88);
  col += fres * alb * 0.16;

  col *= vec3(1.0) - closedSeam * vec3(0.16, 0.23, 0.18);
  gl_FragColor = vec4(min(col, vec3(1.0)) * alpha, alpha);
}`;

/* ---------------- sound ---------------- */

let audio: AudioContext | null = null;

/** A low thud plus muffled cloth, synthesised — no audio file to ship. */
function thump(pitch: number) {
  try {
    const AC = window.AudioContext || (window as any).webkitAudioContext;
    audio = audio ?? new AC();
    const ctx = audio;
    if (ctx.state === "suspended") ctx.resume();
    const t = ctx.currentTime;

    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(130 * pitch, t);
    osc.frequency.exponentialRampToValueAtTime(42 * pitch, t + 0.16);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.55, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.28);
    osc.connect(g).connect(ctx.destination);
    osc.start(t);
    osc.stop(t + 0.3);

    const len = Math.floor(ctx.sampleRate * 0.08);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const noise = ctx.createBufferSource();
    noise.buffer = buf;
    const lp = ctx.createBiquadFilter();
    lp.type = "lowpass";
    lp.frequency.value = 380 * pitch;
    const ng = ctx.createGain();
    ng.gain.value = 0.35;
    noise.connect(lp).connect(ng).connect(ctx.destination);
    noise.start(t);
  } catch {
    /* audio is optional */
  }
}

/* ---------------- component ---------------- */

function compile(gl: WebGLRenderingContext, type: number, src: string) {
  const s = gl.createShader(type)!;
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
    throw new Error(gl.getShaderInfoLog(s) || "shader compile failed");
  }
  return s;
}

function makeTexture(gl: WebGLRenderingContext, unit: number, w: number, h: number, data: Uint8Array) {
  const tex = gl.createTexture();
  gl.activeTexture(gl.TEXTURE0 + unit);
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, data);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  return tex;
}

type PunchProps = {
  src: string;
  material?: Material;
  /** 1 = as drawn; smaller packs the letters closer together */
  squeeze?: number;
};

function PunchDent({ src, material = "leather", squeeze = 0.8 }: PunchProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const P = PRESETS[material];
    let cancelled = false;
    let raf = 0;
    let dispose = () => {};

    const img = new Image();
    // the artwork is read back pixel by pixel, which a cross-origin image would block
    img.crossOrigin = "anonymous";
    img.onerror = () => setFailed(true);
    img.onload = () => {
      if (cancelled) return;
      try {
        dispose = start(canvas, img);
      } catch (err) {
        console.warn("PunchDent: falling back to the flat image —", err);
        setFailed(true);
      }
    };
    img.src = src;

    function start(canvas: HTMLCanvasElement, img: HTMLImageElement) {
      const maps = buildMaps(img, squeeze);
      const aspect = maps.aspect;
      canvas.style.aspectRatio = String(aspect);

      const gl = canvas.getContext("webgl", { premultipliedAlpha: true, alpha: true });
      if (!gl) throw new Error("no webgl");

      const prog = gl.createProgram()!;
      gl.attachShader(prog, compile(gl, gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, compile(gl, gl.FRAGMENT_SHADER, FRAG));
      gl.linkProgram(prog);
      if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
        throw new Error(gl.getProgramInfoLog(prog) || "shader link failed");
      }
      gl.useProgram(prog);

      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
      const aPos = gl.getAttribLocation(prog, "aPos");
      gl.enableVertexAttribArray(aPos);
      gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

      const texShape = makeTexture(gl, 0, maps.W, maps.H, maps.shape);
      const texAlbedo = makeTexture(gl, 1, maps.AW, maps.AH, maps.albedo);
      const texOcc = makeTexture(gl, 2, maps.W, maps.H, maps.occlusion);

      const u = (n: string) => gl.getUniformLocation(prog, n);
      gl.uniform1i(u("uShape"), 0);
      gl.uniform1i(u("uAlbedo"), 1);
      gl.uniform1i(u("uOcclusion"), 2);
      gl.uniform1f(u("uAspect"), aspect);
      gl.uniform1f(u("uEdge"), EDGE);
      gl.uniform1f(u("uGmax"), GMAX);
      gl.uniform1f(u("uAmp"), P.amp);
      gl.uniform1f(u("uRim"), P.rim);
      gl.uniform1f(u("uWrinkle"), P.wrinkle);
      gl.uniform1f(u("uRipple"), P.ripple);
      gl.uniform1f(u("uSpec"), P.spec);
      gl.uniform1f(u("uShine"), P.shine);
      gl.uniform1f(u("uBroad"), P.broad);
      gl.uniform1f(u("uMicro"), P.micro);
      gl.uniform1f(u("uPrint"), P.print);
      gl.uniform1f(u("uSat"), P.sat);
      const uDents = u("uDents[0]");
      const uDentsB = u("uDentsB[0]");
      gl.clearColor(0, 0, 0, 0);

      // only the letters answer a press; the space around them does nothing
      const onLetters = (uu: number, vv: number) => {
        if (uu < 0 || uu > 1 || vv < 0 || vv > 1) return false;
        const x = Math.min(maps.W - 1, Math.floor(uu * maps.W));
        const y = Math.min(maps.H - 1, Math.floor(vv * maps.H));
        return maps.alphaMap[y * maps.W + x] > 100;
      };

      const dents: Dent[] = [];
      const dA = new Float32Array(SLOTS * 4);
      const dB = new Float32Array(SLOTS * 4);

      const draw = (now: number) => {
        raf = 0;
        for (let i = dents.length - 1; i >= 0; i--) {
          const d = dents[i];
          const gone =
            (d.dying !== null && now - d.dying > FADE_MS) ||
            (d.released !== null && P.residual === 0 && depthOf(d, now, P) < 0.004);
          if (gone) dents.splice(i, 1);
        }
        dA.fill(0);
        dB.fill(0);
        dents.forEach((d, i) => {
          dA.set([d.x, d.y, depthOf(d, now, P), d.r], i * 4);
          dB.set([(now - d.t0) / 1000, d.seed, 7 + Math.floor(d.seed * 5), 0], i * 4);
        });
        gl.uniform4fv(uDents, dA);
        gl.uniform4fv(uDentsB, dB);
        gl.clear(gl.COLOR_BUFFER_BIT);
        gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
        canvas.dataset.ready = "true";
        canvas.dataset.dents = String(dents.length);
        // keep animating while anything moves; a settled clay dent needs no more frames
        const moving = dents.some(
          (d) => d.released === null || d.dying !== null || now - (d.released ?? d.t0) < 9000 || P.residual === 0,
        );
        if (dents.length && moving) raf = requestAnimationFrame(draw);
      };
      const kick = () => {
        if (!raf) raf = requestAnimationFrame(draw);
      };

      const resize = () => {
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
        const h = Math.max(1, Math.round(w / aspect));
        if (canvas.width !== w || canvas.height !== h) {
          canvas.width = w;
          canvas.height = h;
        }
        gl.viewport(0, 0, w, h);
        kick();
      };
      const ro = new ResizeObserver(resize);
      ro.observe(canvas);
      resize();

      const toUv = (e: PointerEvent) => {
        const r = canvas.getBoundingClientRect();
        return {
          u: ((e.clientX - r.left) / r.width - EDGE) / (1 - 2 * EDGE),
          v: ((e.clientY - r.top) / r.height - EDGE) / (1 - 2 * EDGE),
        };
      };

      const onDown = (e: PointerEvent) => {
        const { u: uu, v: vv } = toUv(e);
        if (!onLetters(uu, vv)) return;
        try {
          canvas.setPointerCapture(e.pointerId);
        } catch {
          /* synthetic or already-released pointer: the press still counts */
        }
        const now = performance.now();
        dents.push({
          x: uu, y: vv, r: P.radius * (0.9 + Math.random() * 0.2), seed: Math.random(),
          t0: now, released: null, dying: null, pointerId: e.pointerId,
        });
        const alive = dents.filter((d) => d.dying === null);
        if (alive.length > MAX_ALIVE) alive[0].dying = now;
        while (dents.length > SLOTS) dents.shift();
        thump(P.pitch);
        try {
          navigator.vibrate?.(10);
        } catch {
          /* optional */
        }
        kick();
      };
      const onUp = (e: PointerEvent) => {
        const now = performance.now();
        for (const d of dents) if (d.pointerId === e.pointerId && d.released === null) d.released = now;
        kick();
      };
      const onMove = (e: PointerEvent) => {
        const { u: uu, v: vv } = toUv(e);
        canvas.style.cursor = onLetters(uu, vv) ? "pointer" : "default";
      };

      canvas.addEventListener("pointerdown", onDown);
      canvas.addEventListener("pointerup", onUp);
      canvas.addEventListener("pointercancel", onUp);
      canvas.addEventListener("pointermove", onMove);

      return () => {
        ro.disconnect();
        canvas.removeEventListener("pointerdown", onDown);
        canvas.removeEventListener("pointerup", onUp);
        canvas.removeEventListener("pointercancel", onUp);
        canvas.removeEventListener("pointermove", onMove);
        gl.deleteTexture(texShape);
        gl.deleteTexture(texAlbedo);
        gl.deleteTexture(texOcc);
        gl.deleteBuffer(buf);
        gl.deleteProgram(prog);
      };
    }

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      dispose();
    };
  }, [src, material, squeeze]);

  if (failed) return <FlatFallback src={src} />;

  return (
    <canvas
      ref={canvasRef}
      style={{ width: "100%", height: "auto", display: "block", touchAction: "none", userSelect: "none" }}
    />
  );
}

/** No WebGL: the same idea as a plain squash, so a press is still answered. */
function FlatFallback({ src }: { src: string }) {
  const [pressed, setPressed] = useState(false);
  return (
    <img
      src={src}
      alt="PUNCH"
      data-renderer="fallback"
      draggable={false}
      onPointerDown={() => setPressed(true)}
      onPointerUp={() => setPressed(false)}
      onPointerLeave={() => setPressed(false)}
      style={{
        width: "100%",
        display: "block",
        touchAction: "none",
        userSelect: "none",
        transform: pressed ? "scale(0.93)" : "scale(1)",
        transition: pressed
          ? "transform 70ms cubic-bezier(.2,.8,.3,1)"
          : "transform 900ms cubic-bezier(.3,0,.2,1) 180ms",
      }}
    />
  );
}

/* ---------------- page ---------------- */

// ?m=clay swaps the material; the default is the glossy one
const material: Material =
  typeof window !== "undefined" && new URLSearchParams(window.location.search).get("m") === "clay"
    ? "clay"
    : "leather";

const BACKGROUND: Record<Material, string> = {
  leather: "#d8cfe8",
  clay: "#e9c548",
};

export default function App() {
  const [showGesture, setShowGesture] = useState(true);
  return (
    <main
      onPointerDownCapture={() => setShowGesture(false)}
      style={{
        minHeight: "100dvh",
        display: "grid",
        placeItems: "center",
        background: BACKGROUND[material],
        padding: "3vmin",
        boxSizing: "border-box",
        width: "100%",
      }}
    >
      <div style={{ width: "min(100%, 1200px)" }}>
        <PunchDent src={punchSrc} material={material} />
        {showGesture && <div className="press-gesture" aria-hidden="true">
          <svg viewBox="0 0 70 70"><circle className="press-ring" cx="25" cy="24" r="16" fill="none" stroke="white" strokeWidth="1.3"/><path className="press-pointer" d="M25 24 L27 48 L33 42 L39 53 L44 50 L37 39 L46 38 Z" fill="white" stroke="#756f80" strokeWidth="1"/></svg>
        </div>}
        <style>{`.press-gesture{position:fixed;left:61%;top:56%;width:58px;height:58px;opacity:.45;pointer-events:none}.press-gesture svg{width:100%;height:100%;overflow:visible}.press-pointer{transform-origin:25px 24px;animation:press-tap 2.6s ease-in-out infinite}.press-ring{transform-origin:25px 24px;animation:press-ripple 2.6s ease-out infinite}@keyframes press-tap{0%,25%,85%,100%{transform:translate(5px,7px) scale(1)}40%,55%{transform:translate(0,0) scale(.9)}}@keyframes press-ripple{0%,28%,85%,100%{opacity:0;transform:scale(.5)}42%{opacity:.8;transform:scale(.7)}75%{opacity:0;transform:scale(1.5)}}@media(prefers-reduced-motion:reduce){.press-pointer,.press-ring{animation:none}.press-ring{opacity:.5}}`}</style>
      </div>
    </main>
  );
}
